window.__qzParts=window.__qzParts||{};window.__qzParts.sinhhoc=[{"p":"Đơn vị cấu tạo và chức năng cơ bản của mọi cơ thể sống là gì?","o":["Tế bào","Mô","Cơ quan","Hệ cơ quan"],"a":"Tế bào","h":"Mọi cơ thể sống đều được cấu tạo từ đơn vị nhỏ nhất này.","e":"Tế bào là đơn vị cấu tạo và chức năng cơ bản của sự sống; mọi cơ thể sinh vật đều gồm một hoặc nhiều tế bào và mọi hoạt động sống đều diễn ra trong tế bào.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Nhóm nguyên tố đa lượng chủ yếu cấu tạo nên cơ thể sống gồm những nguyên tố nào?","o":["Sắt (Fe), đồng (Cu), kẽm (Zn), iốt (I)","Cacbon (C), hiđrô (H), oxi (O), nitơ (N)","Vàng (Au), bạc (Ag), chì (Pb), thuỷ ngân (Hg)","Heli (He), neon (Ne), agon (Ar), kripton (Kr)"],"a":"Cacbon (C), hiđrô (H), oxi (O), nitơ (N)","h":"Đây là bốn nguyên tố chiếm phần lớn khối lượng cơ thể sống.","e":"C, H, O, N là các nguyên tố đa lượng chiếm tỉ lệ lớn trong cơ thể sống và là thành phần cấu tạo nên các chất hữu cơ như protein, cacbohiđrat, lipit, axit nuclêic.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Nước chiếm khoảng bao nhiêu phần trăm khối lượng cơ thể của hầu hết các loài sinh vật?","o":["Khoảng 20%","Khoảng 40%","Khoảng 70%","Khoảng 99%"],"a":"Khoảng 70%","h":"Nước là thành phần chiếm tỉ lệ lớn nhất trong tế bào.","e":"Nước chiếm khoảng 70% khối lượng cơ thể ở hầu hết sinh vật (tỉ lệ này thay đổi tuỳ loài và độ tuổi), đóng vai trò rất quan trọng đối với sự sống.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Vai trò quan trọng nhất của nước đối với tế bào là gì?","o":["Dự trữ năng lượng cho tế bào","Cấu tạo nên màng tế bào","Lưu trữ thông tin di truyền","Là dung môi hoà tan các chất và là môi trường diễn ra các phản ứng sinh hoá"],"a":"Là dung môi hoà tan các chất và là môi trường diễn ra các phản ứng sinh hoá","h":"Hãy nhớ tính chất phân cực của phân tử nước.","e":"Nhờ tính phân cực, nước hoà tan được nhiều chất và là môi trường cho hầu hết các phản ứng sinh hoá trong tế bào; nước còn tham gia trực tiếp vào một số phản ứng như quang hợp, thuỷ phân.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Tinh bột ở thực vật có chức năng chủ yếu là gì?","o":["Cấu tạo nên thành tế bào","Dự trữ năng lượng","Xúc tác các phản ứng hoá học","Vận chuyển oxi trong cây"],"a":"Dự trữ năng lượng","h":"Củ, hạt giàu tinh bột là kho chứa chất dinh dưỡng của cây.","e":"Tinh bột là cacbohiđrat dự trữ năng lượng ở thực vật, tích luỹ nhiều trong hạt, củ. Xenlulozơ mới là thành phần cấu tạo thành tế bào thực vật.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Xenlulozơ là thành phần cấu tạo chủ yếu của cấu trúc nào?","o":["Màng tế bào động vật","Nhân tế bào","Thành tế bào thực vật","Vỏ hạt gạo"],"a":"Thành tế bào thực vật","h":"Đây là lớp vỏ cứng bao ngoài màng sinh chất của tế bào thực vật.","e":"Xenlulozơ là một loại đường đa (polisaccarit) cấu tạo nên thành tế bào thực vật, giúp tế bào có hình dạng ổn định và được bảo vệ.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Lớp kép phôtpholipit là thành phần cấu tạo chính của cấu trúc nào trong tế bào?","o":["Thành tế bào","Nhân tế bào","Ribôxôm","Màng sinh chất"],"a":"Màng sinh chất","h":"Cấu trúc này bao bọc toàn bộ tế bào chất.","e":"Màng sinh chất được cấu tạo chủ yếu từ một lớp kép phôtpholipit và các phân tử protein nằm xen kẽ, giúp màng có tính thấm chọn lọc.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Đơn phân cấu tạo nên phân tử protein là gì?","o":["Axit amin","Nuclêôtit","Glucozơ","Axit béo"],"a":"Axit amin","h":"Protein là chuỗi pôlipeptit gồm nhiều đơn vị nhỏ liên kết với nhau.","e":"Protein được cấu tạo từ các axit amin liên kết với nhau bằng liên kết peptit tạo thành chuỗi pôlipeptit; có khoảng 20 loại axit amin tham gia cấu tạo protein trong cơ thể sống.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Phân tử ADN có chức năng chính là gì?","o":["Vận chuyển axit amin đến ribôxôm","Xúc tác các phản ứng sinh hoá","Lưu trữ và truyền đạt thông tin di truyền","Dự trữ năng lượng cho tế bào"],"a":"Lưu trữ và truyền đạt thông tin di truyền","h":"ADN nằm chủ yếu trong nhân tế bào và chứa 'bản thiết kế' của cơ thể.","e":"ADN lưu trữ thông tin di truyền dưới dạng trình tự các nuclêôtit và truyền đạt thông tin đó qua các thế hệ tế bào và thế hệ cơ thể.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Loại bazơ nitơ nào có trong ARN mà không có trong ADN?","o":["Ađênin (A)","Guanin (G)","Xitôzin (X)","Uraxin (U)"],"a":"Uraxin (U)","h":"Trong ARN, bazơ này thay thế cho timin (T) của ADN.","e":"ADN gồm các bazơ A, T, G, X; ARN gồm A, U, G, X. Uraxin (U) là bazơ đặc trưng của ARN, thay thế vị trí của timin.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Màng sinh chất cho các chất ra vào tế bào theo cơ chế nào?","o":["Có chọn lọc","Hoàn toàn tự do, không kiểm soát","Chỉ cho phân tử nước đi qua","Không cho bất kì chất nào đi qua"],"a":"Có chọn lọc","h":"Tính chất này giúp tế bào giữ được môi trường nội bào ổn định.","e":"Màng sinh chất có tính thấm chọn lọc: chỉ cho một số chất nhất định đi qua với mức độ khác nhau, nhờ đó tế bào kiểm soát được sự trao đổi chất với môi trường.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Tế bào nhân sơ khác tế bào nhân thực ở đặc điểm cơ bản nào?","o":["Không có màng sinh chất","Chưa có nhân hoàn chỉnh, vật chất di truyền nằm ở vùng nhân không có màng bao bọc","Không có ribôxôm","Không có tế bào chất"],"a":"Chưa có nhân hoàn chỉnh, vật chất di truyền nằm ở vùng nhân không có màng bao bọc","h":"Vi khuẩn là ví dụ điển hình của tế bào nhân sơ.","e":"Tế bào nhân sơ (như vi khuẩn) chưa có nhân hoàn chỉnh: ADN dạng vòng nằm ở vùng nhân không có màng nhân bao bọc, và tế bào không có các bào quan có màng.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Nhân tế bào có chức năng chủ yếu là gì?","o":["Tổng hợp ATP cung cấp năng lượng","Thực hiện quang hợp","Thực hiện hô hấp tế bào","Chứa vật chất di truyền và điều khiển mọi hoạt động sống của tế bào"],"a":"Chứa vật chất di truyền và điều khiển mọi hoạt động sống của tế bào","h":"Nhân được coi là trung tâm điều khiển của tế bào.","e":"Nhân chứa ADN mang thông tin di truyền, qua đó điều khiển quá trình tổng hợp protein và mọi hoạt động sống của tế bào.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Ti thể được gọi là 'nhà máy năng lượng' của tế bào vì sao?","o":["Là nơi diễn ra hô hấp tế bào, tạo ra phần lớn ATP cho tế bào","Là nơi duy nhất chứa ADN của tế bào","Là nơi tổng hợp protein","Là nơi thực hiện quang hợp"],"a":"Là nơi diễn ra hô hấp tế bào, tạo ra phần lớn ATP cho tế bào","h":"ATP là 'đồng tiền năng lượng' của tế bào.","e":"Ti thể là bào quan diễn ra quá trình hô hấp tế bào, phân giải chất hữu cơ để tổng hợp ATP cung cấp năng lượng cho các hoạt động sống.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Lục lạp là bào quan thực hiện chức năng nào?","o":["Hô hấp tế bào","Quang hợp","Tiêu hoá nội bào","Tổng hợp lipit"],"a":"Quang hợp","h":"Lục lạp chứa sắc tố diệp lục có màu xanh.","e":"Lục lạp chứa chất diệp lục, là nơi diễn ra quang hợp ở tế bào thực vật và tảo, chuyển hoá năng lượng ánh sáng thành năng lượng hoá học trong chất hữu cơ.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Ribôxôm trong tế bào là nơi diễn ra quá trình nào?","o":["Tổng hợp lipit","Phân giải các chất thải","Tổng hợp protein","Tổng hợp ATP"],"a":"Tổng hợp protein","h":"Ribôxôm đọc thông tin từ ARN thông tin (mARN).","e":"Ribôxôm là bào quan không có màng, có ở cả tế bào nhân sơ và nhân thực, là nơi các axit amin được liên kết thành chuỗi pôlipeptit theo thông tin di truyền.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Lưới nội chất hạt có đặc điểm và chức năng gì?","o":["Có ribôxôm gắn trên bề mặt, tham gia tổng hợp protein","Không có ribôxôm, chuyên tổng hợp lipit","Chứa chất diệp lục, tham gia quang hợp","Chứa enzim tiêu hoá các chất già cỗi"],"a":"Có ribôxôm gắn trên bề mặt, tham gia tổng hợp protein","h":"Tên gọi 'hạt' xuất phát từ các ribôxôm bám trên màng của nó.","e":"Lưới nội chất hạt có nhiều ribôxôm gắn ở mặt ngoài nên tham gia tổng hợp protein; lưới nội chất trơn không có ribôxôm, tham gia tổng hợp lipit và giải độc.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Vi sinh vật được ứng dụng để sản xuất sữa chua là nhờ quá trình nào?","o":["Quang hợp của vi khuẩn lam","Lên men lactic của vi khuẩn lactic","Hô hấp hiếu khí của nấm men","Cố định nitơ của vi khuẩn nốt sần"],"a":"Lên men lactic của vi khuẩn lactic","h":"Quá trình này biến đường trong sữa thành axit lactic làm sữa chua lại.","e":"Vi khuẩn lactic lên men đường lactozơ trong sữa tạo axit lactic, làm protein sữa đông tụ và tạo vị chua đặc trưng cho sữa chua. Vi sinh vật còn được ứng dụng sản xuất bia, rượu, nước mắm, kháng sinh...","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Ngoài màng sinh chất, tế bào thực vật còn có thành tế bào với vai trò gì?","o":["Tổng hợp protein cho tế bào","Bảo vệ tế bào và giữ cho tế bào có hình dạng ổn định","Tạo năng lượng cho tế bào","Lưu trữ thông tin di truyền"],"a":"Bảo vệ tế bào và giữ cho tế bào có hình dạng ổn định","h":"Thành tế bào cấu tạo chủ yếu từ xenlulozơ.","e":"Thành tế bào thực vật cấu tạo chủ yếu từ xenlulozơ, nằm ngoài màng sinh chất, giúp bảo vệ tế bào và duy trì hình dạng, độ cứng cho mô thực vật.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Đặc điểm chung nổi bật nhất của vi sinh vật là gì?","o":["Đều có nhân hoàn chỉnh","Đều sống được ở nơi có ánh sáng","Đều có kích thước lớn, nhìn thấy bằng mắt thường","Kích thước rất nhỏ bé, chỉ quan sát được dưới kính hiển vi"],"a":"Kích thước rất nhỏ bé, chỉ quan sát được dưới kính hiển vi","h":"Chính đặc điểm này là nguồn gốc của tên gọi 'vi sinh vật'.","e":"Vi sinh vật gồm vi khuẩn, nấm men, nấm mốc, tảo đơn bào... có kích thước hiển vi, phân bố rộng khắp và sinh trưởng, sinh sản rất nhanh.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Vận chuyển thụ động các chất qua màng sinh chất có đặc điểm gì?","o":["Luôn tiêu tốn năng lượng ATP","Các chất di chuyển ngược chiều građien nồng độ","Chỉ diễn ra ở tế bào chết","Không tiêu tốn năng lượng, các chất di chuyển từ nơi có nồng độ cao đến nơi có nồng độ thấp"],"a":"Không tiêu tốn năng lượng, các chất di chuyển từ nơi có nồng độ cao đến nơi có nồng độ thấp","h":"Khuếch tán và thẩm thấu là hai hình thức của vận chuyển thụ động.","e":"Vận chuyển thụ động diễn ra theo chiều građien nồng độ (từ nơi nồng độ cao đến nơi nồng độ thấp) và không cần tế bào tiêu tốn năng lượng ATP.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Khuếch tán là hiện tượng các phân tử chất tan di chuyển như thế nào?","o":["Từ nơi có nồng độ thấp đến nơi có nồng độ cao","Từ nơi có nồng độ cao đến nơi có nồng độ thấp","Nhờ tế bào tiêu tốn năng lượng ATP","Chỉ xảy ra đối với phân tử nước"],"a":"Từ nơi có nồng độ cao đến nơi có nồng độ thấp","h":"Kết quả của khuếch tán là nồng độ chất tan cân bằng ở hai phía màng.","e":"Khuếch tán là sự di chuyển thụ động của các phân tử từ vùng có nồng độ cao đến vùng có nồng độ thấp cho đến khi phân bố đều, không cần cung cấp năng lượng.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Thẩm thấu là hiện tượng gì?","o":["Sự vận chuyển ion qua các kênh protein","Sự di chuyển của phân tử chất tan qua màng","Sự khuếch tán của phân tử nước qua màng bán thấm","Sự nhập bào các giọt chất lỏng"],"a":"Sự khuếch tán của phân tử nước qua màng bán thấm","h":"Nước di chuyển từ nơi có thế nước cao đến nơi có thế nước thấp.","e":"Thẩm thấu là sự khuếch tán của các phân tử nước qua màng bán thấm, từ nơi có nồng độ chất tan thấp (thế nước cao) đến nơi có nồng độ chất tan cao (thế nước thấp).","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Khi đặt tế bào hồng cầu vào môi trường nhược trương, hiện tượng nào sẽ xảy ra?","o":["Tế bào trương nước, có thể bị vỡ ra","Tế bào teo lại, nhăn nheo","Tế bào không thay đổi gì","Xảy ra hiện tượng co nguyên sinh"],"a":"Tế bào trương nước, có thể bị vỡ ra","h":"Môi trường nhược trương có nồng độ chất tan thấp hơn trong tế bào, nước sẽ thẩm thấu vào tế bào.","e":"Trong môi trường nhược trương, nước từ ngoài thẩm thấu vào tế bào hồng cầu làm tế bào trương lên; hồng cầu không có thành tế bào nên có thể bị vỡ (tan huyết). Co nguyên sinh chỉ xảy ra ở tế bào thực vật đặt trong môi trường ưu trương.","t":"sinh-lop10","g":10,"l":"thu-thach"},{"p":"Vận chuyển chủ động khác vận chuyển thụ động ở điểm cơ bản nào?","o":["Luôn diễn ra qua lớp kép phôtpholipit","Không cần màng sinh chất tham gia","Tiêu tốn năng lượng ATP và có thể di chuyển các chất ngược chiều građien nồng độ","Chỉ vận chuyển được phân tử nước"],"a":"Tiêu tốn năng lượng ATP và có thể di chuyển các chất ngược chiều građien nồng độ","h":"Nhờ cơ chế này, tế bào hấp thu được cả những chất đang có nồng độ thấp ở môi trường.","e":"Vận chuyển chủ động cần năng lượng ATP và các protein vận chuyển đặc hiệu, giúp tế bào đưa các chất từ nơi có nồng độ thấp đến nơi có nồng độ cao, ngược chiều građien.","t":"sinh-lop10","g":10,"l":"thu-thach"},{"p":"Hiện tượng co nguyên sinh ở tế bào thực vật xảy ra khi đặt tế bào vào môi trường nào?","o":["Ưu trương","Nhược trương","Đẳng trương","Nước cất"],"a":"Ưu trương","h":"Trong môi trường này, nước từ trong tế bào đi ra ngoài.","e":"Khi đặt tế bào thực vật vào môi trường ưu trương (nồng độ chất tan bên ngoài cao hơn trong tế bào), nước thẩm thấu ra ngoài làm tế bào chất và màng sinh chất co lại, tách khỏi thành tế bào — đó là hiện tượng co nguyên sinh.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Bản chất hoá học của đa số enzim là gì?","o":["Lipit","Cacbohiđrat","Axit nuclêic","Protein"],"a":"Protein","h":"Vì vậy enzim dễ bị biến tính khi nhiệt độ quá cao.","e":"Đa số enzim là protein (một số ít là ARN có hoạt tính xúc tác). Bản chất protein khiến enzim có cấu trúc không gian đặc trưng và tính đặc hiệu cao với cơ chất.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Mỗi loại enzim thường chỉ xúc tác cho một hoặc một số phản ứng nhất định với cơ chất xác định. Điều đó thể hiện tính chất nào của enzim?","o":["Tính bền với nhiệt độ","Tính hoà tan trong nước","Tính đặc hiệu","Tính lưỡng tính"],"a":"Tính đặc hiệu","h":"Trung tâm hoạt động của enzim chỉ khớp với cơ chất có cấu trúc phù hợp như 'ổ khoá - chìa khoá'.","e":"Enzim có tính đặc hiệu cao vì trung tâm hoạt động của enzim chỉ liên kết được với cơ chất có cấu hình không gian phù hợp, nên mỗi enzim thường chỉ xúc tác cho một loại phản ứng.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Khi nhiệt độ môi trường tăng quá cao vượt ngưỡng chịu đựng, enzim sẽ bị ảnh hưởng như thế nào?","o":["Hoạt tính tăng lên mãi không giới hạn","Biến tính, mất hoạt tính xúc tác","Chuyển hoá thành cơ chất","Tự nhân đôi để tăng số lượng"],"a":"Biến tính, mất hoạt tính xúc tác","h":"Enzim có bản chất protein nên cấu trúc không gian dễ bị phá vỡ bởi nhiệt độ cao.","e":"Nhiệt độ cao làm phá vỡ các liên kết yếu duy trì cấu trúc không gian của protein enzim, khiến trung tâm hoạt động biến dạng và enzim mất hoạt tính (biến tính).","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"ATP được ví là 'đồng tiền năng lượng' của tế bào vì lí do nào?","o":["ATP có rất nhiều trong nhân tế bào","ATP là chất dự trữ năng lượng dài hạn","ATP rất khó bị phân giải","ATP dễ dàng giải phóng năng lượng để cung cấp cho mọi hoạt động sống của tế bào"],"a":"ATP dễ dàng giải phóng năng lượng để cung cấp cho mọi hoạt động sống của tế bào","h":"Năng lượng tích trong các liên kết phôtphat của ATP được giải phóng khi cần.","e":"ATP (ađenôzin triphôtphat) khi thuỷ phân thành ADP và nhóm phôtphat sẽ giải phóng năng lượng dùng ngay cho các hoạt động như tổng hợp chất, vận chuyển chủ động, co cơ... nên được coi là đồng tiền năng lượng của tế bào.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Hô hấp tế bào là quá trình nào sau đây?","o":["Phân giải chất hữu cơ để giải phóng năng lượng tích luỹ trong ATP","Tổng hợp chất hữu cơ từ khí cacbonic và nước","Trao đổi khí qua bề mặt cơ thể","Vận chuyển oxi trong máu"],"a":"Phân giải chất hữu cơ để giải phóng năng lượng tích luỹ trong ATP","h":"Glucose là nguyên liệu điển hình của quá trình này.","e":"Hô hấp tế bào phân giải các chất hữu cơ (chủ yếu là glucose) thành CO2 và nước, đồng thời giải phóng năng lượng để tổng hợp ATP cung cấp cho hoạt động sống.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Ở tế bào nhân thực, quá trình hô hấp tế bào diễn ra chủ yếu ở bào quan nào?","o":["Lục lạp","Nhân tế bào","Ti thể","Ribôxôm"],"a":"Ti thể","h":"Đây là bào quan được gọi là 'nhà máy năng lượng'.","e":"Ti thể là nơi diễn ra hô hấp tế bào ở sinh vật nhân thực, tạo ra phần lớn lượng ATP mà tế bào sử dụng.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Khi hoạt động mạnh trong điều kiện thiếu oxi, tế bào cơ của người có thể lên men lactic tạo ra sản phẩm nào?","o":["Axit lactic","Glucozơ","Khí oxi","Protein"],"a":"Axit lactic","h":"Chính sản phẩm này tích tụ gây mỏi cơ khi vận động quá sức.","e":"Khi thiếu oxi, tế bào cơ lên men lactic: glucose bị phân giải không hoàn toàn thành axit lactic và chỉ tạo được rất ít ATP (2 ATP) so với hô hấp hiếu khí, axit lactic tích tụ gây mỏi cơ.","t":"sinh-lop10","g":10,"l":"thu-thach"},{"p":"Pha sáng của quang hợp diễn ra ở vị trí nào và cần điều kiện gì?","o":["Ở chất nền của lục lạp, không cần ánh sáng","Ở ti thể, cần khí oxi","Ở tế bào chất, cần nhiệt độ cao","Ở màng tilacôit của lục lạp, cần năng lượng ánh sáng"],"a":"Ở màng tilacôit của lục lạp, cần năng lượng ánh sáng","h":"Pha sáng chuyển hoá năng lượng ánh sáng thành ATP và NADPH.","e":"Pha sáng diễn ra trên màng tilacôit của lục lạp khi có ánh sáng: nước bị phân li giải phóng oxi, đồng thời tạo ATP và NADPH cung cấp cho pha tối.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Pha tối của quang hợp (chu trình Canvin) sử dụng trực tiếp những sản phẩm nào của pha sáng?","o":["Oxi và glucozơ","Khí cacbonic và nước","ATP và NADPH","ADP và NADP+"],"a":"ATP và NADPH","h":"Pha tối diễn ra ở chất nền lục lạp và là pha cố định CO2.","e":"Pha tối diễn ra ở chất nền (strôma) của lục lạp, sử dụng ATP và NADPH do pha sáng tạo ra để khử CO2 thành chất hữu cơ (đường).","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Khí oxi được giải phóng ra trong quá trình quang hợp có nguồn gốc từ đâu?","o":["Từ phân tử khí cacbonic (CO2)","Từ phân tử nước (H2O)","Từ phân tử glucozơ","Từ không khí hấp thụ qua khí khổng"],"a":"Từ phân tử nước (H2O)","h":"Trong pha sáng, nước bị phân li dưới tác dụng của ánh sáng.","e":"Thí nghiệm với nước đánh dấu đồng vị oxi cho thấy toàn bộ oxi thoát ra trong quang hợp bắt nguồn từ sự quang phân li nước ở pha sáng, không phải từ CO2.","t":"sinh-lop10","g":10,"l":"thu-thach"},{"p":"Trong kì trung gian của chu kì tế bào, ADN được nhân đôi ở pha nào?","o":["Pha G1","Pha G2","Pha M","Pha S"],"a":"Pha S","h":"Tên pha S bắt nguồn từ 'synthesis' - tổng hợp ADN.","e":"Kì trung gian gồm các pha G1, S, G2. Ở pha S, ADN và nhiễm sắc thể được nhân đôi, chuẩn bị cho quá trình phân bào diễn ra chính xác.","t":"sinh-lop10","g":10,"l":"thu-thach"},{"p":"Từ một tế bào mẹ lưỡng bội (2n), nguyên phân tạo ra kết quả nào?","o":["Bốn tế bào con đơn bội (n)","Hai tế bào con đơn bội (n)","Hai tế bào con có bộ nhiễm sắc thể 2n giống hệt tế bào mẹ","Một tế bào con có bộ nhiễm sắc thể 4n"],"a":"Hai tế bào con có bộ nhiễm sắc thể 2n giống hệt tế bào mẹ","h":"Nguyên phân là cơ chế giúp cơ thể đa bào sinh trưởng và tái tạo tế bào.","e":"Nguyên phân gồm một lần phân bào, tạo hai tế bào con có số lượng và cấu trúc nhiễm sắc thể giống hệt tế bào mẹ (2n), giúp cơ thể sinh trưởng, phát triển và thay thế tế bào già, tổn thương.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Giảm phân tạo ra các tế bào con có số lượng nhiễm sắc thể như thế nào so với tế bào mẹ?","o":["Tăng gấp đôi so với tế bào mẹ","Giảm đi một nửa so với tế bào mẹ","Giữ nguyên như tế bào mẹ","Bằng không"],"a":"Giảm đi một nửa so với tế bào mẹ","h":"Giảm phân là cơ chế tạo giao tử ở sinh vật sinh sản hữu tính.","e":"Qua hai lần phân bào liên tiếp (giảm phân I và II), một tế bào mẹ 2n tạo bốn tế bào con đơn bội (n); khi thụ tinh, giao tử đực và cái kết hợp khôi phục lại bộ nhiễm sắc thể 2n.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Virus khác hẳn các sinh vật khác ở đặc điểm nào?","o":["Chưa có cấu tạo tế bào, chỉ sống và nhân lên được khi kí sinh bắt buộc trong tế bào sống","Có ribôxôm riêng để tự tổng hợp protein","Tự tổng hợp được ATP cho hoạt động sống","Có nhân hoàn chỉnh chứa ADN"],"a":"Chưa có cấu tạo tế bào, chỉ sống và nhân lên được khi kí sinh bắt buộc trong tế bào sống","h":"Vì đặc điểm này, nhiều bệnh do virus gây ra rất khó điều trị bằng kháng sinh.","e":"Virus chưa có cấu tạo tế bào, chỉ gồm vỏ protein và lõi axit nuclêic (ADN hoặc ARN), không tự trao đổi chất được nên bắt buộc phải kí sinh trong tế bào chủ để nhân lên — đây cũng là cơ chế gây bệnh của virus.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Ở kì giữa của nguyên phân, các nhiễm sắc thể kép có đặc điểm nào nổi bật nhất?","o":["Co xoắn cực đại và xếp thành một hàng trên mặt phẳng xích đạo của thoi phân bào","Dãn xoắn hoàn toàn thành dạng sợi mảnh","Phân li về hai cực của tế bào","Bắt đầu nhân đôi để tạo nhiễm sắc thể kép"],"a":"Co xoắn cực đại và xếp thành một hàng trên mặt phẳng xích đạo của thoi phân bào","h":"Đây là kì mà nhiễm sắc thể nhìn rõ nhất dưới kính hiển vi.","e":"Ở kì giữa, nhiễm sắc thể kép co xoắn cực đại và xếp thành một hàng trên mặt phẳng xích đạo, nên đây là giai đoạn quan sát và đếm nhiễm sắc thể rõ nhất.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Từ một tế bào mẹ lưỡng bội (2n) trải qua giảm phân sẽ tạo ra","o":["2 tế bào con có bộ nhiễm sắc thể 2n","4 tế bào con có bộ nhiễm sắc thể đơn bội (n)","4 tế bào con có bộ nhiễm sắc thể 2n","2 tế bào con có bộ nhiễm sắc thể n"],"a":"4 tế bào con có bộ nhiễm sắc thể đơn bội (n)","h":"Giảm phân gồm hai lần phân bào liên tiếp và làm giảm một nửa số nhiễm sắc thể.","e":"Qua giảm phân I và giảm phân II, một tế bào 2n tạo thành 4 tế bào con đơn bội (n), là cơ sở hình thành giao tử trong sinh sản hữu tính.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Khi chu kì tế bào bị mất kiểm soát, tế bào phân chia liên tục không ngừng và hình thành khối u, hiện tượng này liên quan đến bệnh nào sau đây?","o":["Bệnh tiểu đường","Bệnh ung thư","Bệnh thiếu máu","Bệnh viêm gan"],"a":"Bệnh ung thư","h":"Khối u ác tính có thể xâm lấn và di căn sang các mô khác.","e":"Ung thư là hệ quả của sự rối loạn cơ chế điều hoà phân bào: tế bào phân chia không kiểm soát tạo khối u, khối u ác tính có khả năng xâm lấn và di căn.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Trong sản xuất bánh mì và rượu, con người đã ứng dụng quá trình lên men của vi sinh vật nào?","o":["Vi khuẩn lactic","Vi khuẩn lam","Nấm men","Nấm mốc xanh"],"a":"Nấm men","h":"Vi sinh vật này lên men đường tạo khí CO₂ làm bánh nở xốp và tạo etanol trong sản xuất rượu.","e":"Nấm men lên men đường: khí CO₂ sinh ra làm bột bánh nở, còn etanol tạo thành là cơ sở của công nghệ sản xuất rượu, bia.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Nhận định nào sau đây đúng khi so sánh vai trò của vi khuẩn trong tự nhiên và đời sống?","o":["Mọi vi khuẩn đều gây bệnh cho người","Vi khuẩn chỉ sống được trong cơ thể sinh vật khác","Vi khuẩn có loại gây bệnh, nhưng nhiều loại có lợi như vi khuẩn cố định đạm và vi khuẩn phân giải chất hữu cơ","Vi khuẩn không tham gia vào chu trình vật chất trong tự nhiên"],"a":"Vi khuẩn có loại gây bệnh, nhưng nhiều loại có lợi như vi khuẩn cố định đạm và vi khuẩn phân giải chất hữu cơ","h":"Hãy nghĩ tới vi khuẩn nốt sần ở rễ cây họ đậu và vi khuẩn trong đất.","e":"Bên cạnh một số vi khuẩn gây bệnh, nhiều vi khuẩn có lợi: vi khuẩn cố định đạm làm giàu đạm cho đất, vi khuẩn phân giải xác sinh vật giúp khép kín chu trình vật chất.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Vì sao biện pháp tiêm vắc xin và giữ vệ sinh cá nhân, môi trường được coi là cách phòng tránh hiệu quả các bệnh do virus gây ra?","o":["Vì virus có thể tự sinh trưởng và phát triển ngoài tế bào chủ","Vì bệnh do virus khó điều trị bằng kháng sinh nên cần chủ động tạo miễn dịch và cắt đứt đường lây truyền","Vì vắc xin tiêu diệt trực tiếp mọi virus ngoài môi trường","Vì virus chỉ lây qua đường thức ăn và nước uống"],"a":"Vì bệnh do virus khó điều trị bằng kháng sinh nên cần chủ động tạo miễn dịch và cắt đứt đường lây truyền","h":"Kháng sinh không có tác dụng với virus; phòng bệnh là chính.","e":"Virus kí sinh nội bào bắt buộc và không bị kháng sinh tiêu diệt, nên phòng bệnh bằng vắc xin (tạo miễn dịch chủ động) kết hợp vệ sinh cá nhân, môi trường để ngăn đường lây là biện pháp hiệu quả nhất.","t":"sinh-lop10","g":10,"l":"nhe-nhang"},{"p":"Quang hợp ở cây xanh diễn ra chủ yếu ở cơ quan nào?","o":["Rễ","Thân","Lá","Hoa"],"a":"Lá","h":"Hãy nhớ cơ quan chứa nhiều lục lạp nhất của cây.","e":"Lá là cơ quan quang hợp chính vì lá có nhiều lục lạp chứa diệp lục và diện tích bề mặt lớn.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Sắc tố nào làm cho lá cây có màu xanh và trực tiếp tham gia quang hợp?","o":["Carôtenôit","Diệp lục","Xantôphin","Anthôcyanin"],"a":"Diệp lục","h":"Sắc tố này hấp thụ ánh sáng đỏ và xanh tím.","e":"Diệp lục là sắc tố quang hợp chính, tạo màu xanh cho lá; các sắc tố phụ chỉ hỗ trợ hấp thụ ánh sáng.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Pha sáng của quang hợp diễn ra ở cấu trúc nào trong lục lạp?","o":["Màng tilacôit","Chất nền (strôma)","Màng trong của ti thể","Nhân tế bào"],"a":"Màng tilacôit","h":"Pha sáng cần ánh sáng trực tiếp và xảy ra trên hệ thống màng trong lục lạp.","e":"Pha sáng diễn ra trên màng tilacôit của lục lạp, nơi có hệ sắc tố và chuỗi chuyền điện tử.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Sản phẩm của pha sáng quang hợp gồm những chất nào?","o":["Glucozơ và CO2","Chỉ có glucozơ","ATP, NADPH và O2","ATP và CO2"],"a":"ATP, NADPH và O2","h":"Pha sáng phân li nước, giải phóng một khí và tạo hai hợp chất giàu năng lượng.","e":"Pha sáng phân li nước tạo O2, đồng thời tổng hợp ATP và NADPH dùng cho pha tối.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Trong pha tối (chu trình Canvin), CO2 được khử thành chất hữu cơ nhờ sử dụng trực tiếp sản phẩm nào của pha sáng?","o":["ATP và NADPH","O2 và nước","Chỉ có O2","Glucozơ và ATP"],"a":"ATP và NADPH","h":"Chu trình Canvin không cần ánh sáng trực tiếp nhưng cần sản phẩm của pha sáng.","e":"Chu trình Canvin dùng ATP và NADPH của pha sáng để khử CO2 thành chất hữu cơ.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Nguyên liệu của quá trình quang hợp là gì?","o":["O2 và glucozơ","CO2 và nước","CO2 và glucozơ","O2 và nước"],"a":"CO2 và nước","h":"Hãy nhớ phương trình tổng quát của quang hợp.","e":"Quang hợp sử dụng CO2 và nước, nhờ năng lượng ánh sáng tạo chất hữu cơ và giải phóng O2.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Nước và muối khoáng từ đất được rễ cây hấp thụ chủ yếu qua bộ phận nào?","o":["Chóp rễ","Lông hút ở miền lông hút","Miền trưởng thành","Mạch gỗ của rễ"],"a":"Lông hút ở miền lông hút","h":"Đây là bộ phận chuyên hoá của tế bào biểu bì rễ, có thành mỏng và không thấm cutin.","e":"Lông hút ở miền lông hút là bộ phận chính hấp thụ nước và muối khoáng của rễ.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Dòng nước và muối khoáng từ rễ lên lá được vận chuyển trong cấu trúc nào?","o":["Mạch rây","Mạch gỗ","Tế bào nhu mô vỏ","Khí khổng"],"a":"Mạch gỗ","h":"Một dòng đi lên chở nguyên liệu vô cơ, một dòng chở sản phẩm hữu cơ của lá.","e":"Mạch gỗ (xilem) dẫn nước và muối khoáng từ rễ lên thân, lá theo dòng đi lên.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Dòng mạch rây trong cây vận chuyển chủ yếu chất nào?","o":["Chất hữu cơ (đường) từ lá tới các cơ quan khác","Nước và muối khoáng từ rễ lên lá","CO2 từ lá xuống rễ","O2 từ lá tới thân"],"a":"Chất hữu cơ (đường) từ lá tới các cơ quan khác","h":"Dòng này bắt đầu từ cơ quan nguồn là lá.","e":"Mạch rây (phloem) vận chuyển chất hữu cơ từ lá đến các cơ quan tiêu thụ hoặc dự trữ.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Ở lá, quá trình thoát hơi nước diễn ra chủ yếu qua cấu trúc nào?","o":["Khí khổng","Biểu bì lá","Mạch gỗ","Lông hút"],"a":"Khí khổng","h":"Đây là cấu trúc gồm hai tế bào hình hạt đậu, đóng mở được.","e":"Hơn 90% lượng nước thoát ra ở lá qua khí khổng; khí khổng còn là nơi trao đổi khí.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Hô hấp tế bào ở thực vật phân giải glucozơ chủ yếu để tạo ra dạng năng lượng nào cho tế bào sử dụng?","o":["Nhiệt năng là chính","Ánh sáng","CO2","ATP"],"a":"ATP","h":"Năng lượng trong glucozơ được chuyển sang đồng tiền năng lượng của tế bào.","e":"Hô hấp tế bào phân giải glucozơ và tích luỹ năng lượng chủ yếu dưới dạng ATP.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Tiêu hoá hoá học ở động vật là quá trình nào?","o":["Nghiền nhỏ thức ăn bằng răng","Đẩy thức ăn dọc ống tiêu hoá","Biến đổi thức ăn nhờ enzim thành các chất đơn giản hấp thụ được","Hấp thụ nước ở ruột già"],"a":"Biến đổi thức ăn nhờ enzim thành các chất đơn giản hấp thụ được","h":"Chú ý từ khoá: biến đổi nhờ enzim.","e":"Tiêu hoá hoá học là sự phân giải thức ăn bởi enzim thành chất đơn giản; nghiền nát thức ăn là tiêu hoá cơ học.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Ở người, chất dinh dưỡng được hấp thụ chủ yếu ở cơ quan nào?","o":["Ruột non","Dạ dày","Ruột già","Thực quản"],"a":"Ruột non","h":"Cơ quan này dài, có nhung mao làm tăng diện tích hấp thụ.","e":"Ruột non có nhung mao và vi nhung mao làm diện tích hấp thụ rất lớn nên là nơi hấp thụ chủ yếu.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Sự trao đổi khí giữa máu và không khí ở phổi người diễn ra tại cấu trúc nào?","o":["Khí quản","Phế quản","Thanh quản","Phế nang"],"a":"Phế nang","h":"Đây là các túi khí nhỏ ở đầu tận của phế quản, bao quanh bởi mao mạch.","e":"Phế nang có thành mỏng, bao quanh bởi mạng mao mạch dày đặc, rất thuận lợi cho trao đổi khí.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Cơ chế trao đổi khí ở phế nang dựa trên nguyên tắc nào?","o":["Vận chuyển chủ động tốn ATP","Thẩm thấu của nước","Bơm khí của cơ hoành","Khuếch tán từ nơi có nồng độ cao đến nơi có nồng độ thấp"],"a":"Khuếch tán từ nơi có nồng độ cao đến nơi có nồng độ thấp","h":"Khí di chuyển theo chiều chênh lệch nồng độ, không tốn năng lượng.","e":"O2 và CO2 qua màng phế nang theo cơ chế khuếch tán, từ nơi nồng độ cao sang nơi nồng độ thấp.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Tim người gồm có mấy ngăn?","o":["2 ngăn","4 ngăn (2 tâm nhĩ, 2 tâm thất)","3 ngăn","5 ngăn"],"a":"4 ngăn (2 tâm nhĩ, 2 tâm thất)","h":"Tim có hai nửa trái - phải, mỗi nửa có một ngăn trên và một ngăn dưới.","e":"Tim người có 4 ngăn: tâm nhĩ phải, tâm nhĩ trái, tâm thất phải và tâm thất trái.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Máu giàu O2 rời tim đi nuôi cơ thể qua mạch nào?","o":["Tĩnh mạch chủ","Động mạch phổi","Động mạch chủ","Tĩnh mạch phổi"],"a":"Động mạch chủ","h":"Đây là động mạch lớn nhất, xuất phát từ tâm thất trái.","e":"Động mạch chủ đưa máu giàu O2 từ tâm thất trái đi khắp cơ thể; động mạch phổi chở máu nghèo O2 lên phổi.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Đơn vị cấu tạo và chức năng của thận là gì?","o":["Phế nang","Nơron","Nhung mao ruột","Nêphron (đơn vị thận)"],"a":"Nêphron (đơn vị thận)","h":"Mỗi thận có khoảng một triệu đơn vị lọc máu như vậy.","e":"Nêphron gồm cầu thận và ống thận, là đơn vị thực hiện lọc máu và tạo nước tiểu của thận.","t":"sinh-lop11","g":11,"l":"thu-thach"},{"p":"Chồi cây mọc cong về phía có ánh sáng thể hiện tính hướng động nào?","o":["Hướng trọng lực dương","Hướng sáng dương","Hướng hoá","Ứng động sinh trưởng"],"a":"Hướng sáng dương","h":"Ngọn cây luôn tìm về phía nguồn sáng.","e":"Chồi cây có tính hướng sáng dương nên mọc cong về phía ánh sáng; đây là hướng động sinh trưởng.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Rễ cây luôn mọc hướng xuống sâu trong đất chủ yếu do tính hướng động nào?","o":["Hướng sáng dương","Hướng nước âm","Hướng trọng lực dương","Hướng tiếp xúc"],"a":"Hướng trọng lực dương","h":"Trọng lực là tác nhân kích thích trong trường hợp này.","e":"Rễ có tính hướng trọng lực dương (mọc theo chiều trọng lực), còn chồi hướng trọng lực âm.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Hiện tượng lá cây trinh nữ cụp xuống khi bị chạm vào thuộc hình thức cảm ứng nào?","o":["Ứng động không định hướng","Hướng động tiếp xúc","Hướng hoá","Hướng trọng lực"],"a":"Ứng động không định hướng","h":"Phản ứng này không theo hướng của tác nhân chạm vào mà do thay đổi sức trương nước.","e":"Lá trinh nữ cụp do thay đổi sức trương nước ở thể gối, không phụ thuộc hướng chạm nên là ứng động.","t":"sinh-lop11","g":11,"l":"thu-thach"},{"p":"Rễ cây mọc hướng về phía nguồn phân bón trong đất thể hiện tính hướng động nào?","o":["Hướng sáng","Hướng trọng lực âm","Ứng động nở hoa","Hướng hoá dương"],"a":"Hướng hoá dương","h":"Tác nhân kích thích ở đây là chất hoá học (phân bón).","e":"Rễ hướng về nơi có chất khoáng cần thiết là hướng hoá dương; ngược lại, rễ tránh chất độc là hướng hoá âm.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Tập tính nào sau đây là tập tính bẩm sinh ở động vật?","o":["Nhện giăng lưới bắt mồi","Chó làm theo hiệu lệnh của người huấn luyện","Mèo được dạy đi vệ sinh đúng chỗ","Khỉ học cách dùng que lấy thức ăn"],"a":"Nhện giăng lưới bắt mồi","h":"Tập tính bẩm sinh có ngay từ khi sinh ra, không qua học tập.","e":"Nhện giăng lưới là tập tính bẩm sinh: sinh ra đã có, mang tính bản năng và di truyền.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Điểm khác biệt cơ bản của tập tính học được so với tập tính bẩm sinh là gì?","o":["Được di truyền từ bố mẹ sang con","Xuất hiện ngay từ khi sinh ra","Chung cho mọi cá thể trong loài","Hình thành trong đời sống cá thể thông qua học tập và rút kinh nghiệm"],"a":"Hình thành trong đời sống cá thể thông qua học tập và rút kinh nghiệm","h":"Tập tính này thay đổi được trong quá trình sống của từng cá thể.","e":"Tập tính học được hình thành qua trải nghiệm của cá thể, có thể thay đổi; tập tính bẩm sinh thì di truyền và bền vững.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Mô phân sinh đỉnh ở thực vật nằm ở vị trí nào?","o":["Trong tầng phát sinh ở thân gỗ","Ở lóng của cây họ Hoà thảo","Trong lá trưởng thành","Đỉnh chồi và đỉnh rễ"],"a":"Đỉnh chồi và đỉnh rễ","h":"Mô này nằm ở đầu tận cùng của thân và rễ, giúp cây dài ra.","e":"Mô phân sinh đỉnh ở đỉnh chồi và đỉnh rễ giúp cây sinh trưởng sơ cấp, tăng chiều dài.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Sinh trưởng thứ cấp làm thân cây hai lá mầm thân gỗ to ra theo chiều ngang nhờ hoạt động của cấu trúc nào?","o":["Mô phân sinh đỉnh","Mô phân sinh lóng","Lông hút","Mô phân sinh bên (tầng phát sinh)"],"a":"Mô phân sinh bên (tầng phát sinh)","h":"Nhờ mô này mà vòng gỗ hằng năm hình thành trong thân cây gỗ.","e":"Tầng phát sinh (mô phân sinh bên) tạo gỗ và libe thứ cấp, làm thân cây gỗ tăng đường kính.","t":"sinh-lop11","g":11,"l":"thu-thach"},{"p":"Hoocmôn auxin ở thực vật có tác dụng chủ yếu nào?","o":["Thúc quả mau chín","Ức chế nảy mầm của hạt","Kích thích tế bào kéo dài, thúc đẩy sinh trưởng và ưu thế đỉnh","Làm lá mau rụng"],"a":"Kích thích tế bào kéo dài, thúc đẩy sinh trưởng và ưu thế đỉnh","h":"Hoocmôn này do chồi đỉnh sinh ra, làm chồi đỉnh lấn át chồi bên.","e":"Auxin kích thích sự kéo dài tế bào, gây ưu thế đỉnh và kích thích ra rễ ở cành giâm.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Hoocmôn giberelin ở thực vật có vai trò nổi bật nào?","o":["Thúc chín quả","Kích thích hạt nảy mầm và thân kéo dài lóng","Gây rụng lá, quả","Ức chế sinh trưởng của chồi"],"a":"Kích thích hạt nảy mầm và thân kéo dài lóng","h":"Hoocmôn này được dùng để phá ngủ của hạt và kéo dài lóng cây.","e":"Giberelin phá trạng thái ngủ của hạt, kích thích nảy mầm và kéo dài lóng thân.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Phát triển qua biến thái hoàn toàn gặp ở động vật nào sau đây?","o":["Châu chấu","Bướm","Gián","Ếch"],"a":"Bướm","h":"Ở biến thái hoàn toàn, ấu trùng khác hẳn dạng trưởng thành (sâu khác bướm).","e":"Bướm phát triển qua biến thái hoàn toàn: trứng - ấu trùng (sâu) - nhộng - bướm trưởng thành; châu chấu và gián phát triển qua biến thái không hoàn toàn.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Giâm cành, chiết cành, ghép cành thuộc hình thức sinh sản nào ở thực vật?","o":["Sinh sản hữu tính","Sinh sản bằng bào tử","Sinh sản vô tính","Sinh sản sinh dưỡng nhân tạo là hữu tính"],"a":"Sinh sản vô tính","h":"Các cách nhân giống này không qua hoa, quả, hạt.","e":"Giâm, chiết, ghép đều là sinh sản vô tính (sinh dưỡng nhân tạo) vì cây con tạo thành từ cơ quan sinh dưỡng của cây mẹ.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Ưu điểm nổi bật của nuôi cấy mô tế bào thực vật là gì?","o":["Tạo được số lượng lớn cây con giống hệt cây mẹ và sạch bệnh","Tạo cây con có nhiều biến dị mới","Không cần điều kiện vô trùng","Cây con luôn khoẻ hơn cây mẹ về mọi mặt"],"a":"Tạo được số lượng lớn cây con giống hệt cây mẹ và sạch bệnh","h":"Kĩ thuật này thực hiện trong phòng thí nghiệm với môi trường dinh dưỡng vô trùng.","e":"Nuôi cấy mô tạo cây con đồng nhất về kiểu gen với cây mẹ, số lượng lớn và sạch bệnh.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Thụ phấn ở thực vật có hoa là quá trình nào?","o":["Hạt phấn nảy mầm thành ống phấn","Giao tử đực kết hợp với trứng","Hạt phấn được chuyển tới đầu nhuỵ của hoa","Noãn phát triển thành hạt"],"a":"Hạt phấn được chuyển tới đầu nhuỵ của hoa","h":"Đây là bước xảy ra trước thụ tinh, nhờ gió hoặc côn trùng.","e":"Thụ phấn là sự chuyển hạt phấn từ bao phấn tới đầu nhuỵ; sau thụ phấn mới có thể xảy ra thụ tinh.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Trong thụ tinh kép ở thực vật hạt kín, nội nhũ (phần dự trữ dinh dưỡng của hạt) được hình thành từ sự kết hợp nào?","o":["Một giao tử đực kết hợp với nhân lưỡng bội (2n) tạo tế bào 3n","Giao tử đực kết hợp với trứng tạo hợp tử 2n","Hai giao tử đực kết hợp với nhau","Trứng kết hợp với nhân cực tạo tế bào 2n"],"a":"Một giao tử đực kết hợp với nhân lưỡng bội (2n) tạo tế bào 3n","h":"Nội nhũ có bộ nhiễm sắc thể 3n.","e":"Ở thụ tinh kép, một giao tử đực (n) kết hợp nhân lưỡng bội (2n) của tế bào trung tâm tạo nội nhũ 3n dự trữ dinh dưỡng.","t":"sinh-lop11","g":11,"l":"thu-thach"},{"p":"Hình thức sinh sản vô tính chủ yếu ở thuỷ tức là gì?","o":["Phân đôi","Nảy chồi","Phân mảnh","Trinh sinh"],"a":"Nảy chồi","h":"Cơ thể con mọc ra ngay trên cơ thể mẹ rồi mới tách ra.","e":"Thuỷ tức sinh sản vô tính bằng nảy chồi: chồi mọc trên cơ thể mẹ, lớn dần rồi tách thành cá thể mới.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Thụ tinh ngoài thường gặp ở nhóm động vật nào?","o":["Chim và thú","Bò sát trên cạn","Cá và ếch (động vật sống hoặc sinh sản trong môi trường nước)","Côn trùng trên cạn"],"a":"Cá và ếch (động vật sống hoặc sinh sản trong môi trường nước)","h":"Hiểu tinh ngoài đòi hỏi môi trường nước để tinh trùng bơi tới trứng.","e":"Cá và ếch đẻ trứng, thụ tinh trong môi trường nước nên là thụ tinh ngoài.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Tim người gồm 4 ngăn (2 tâm nhĩ, 2 tâm thất) với vách ngăn hoàn toàn. Đặc điểm này có ý nghĩa gì?","o":["Giúp máu giàu ôxi và máu giàu CO₂ không bị trộn lẫn, đảm bảo hiệu quả trao đổi khí","Giúp tim co bóp nhanh hơn tim của mọi loài động vật khác","Giúp máu chỉ chảy trong động mạch mà không chảy trong tĩnh mạch","Giúp cơ thể không cần phổi để trao đổi khí"],"a":"Giúp máu giàu ôxi và máu giàu CO₂ không bị trộn lẫn, đảm bảo hiệu quả trao đổi khí","h":"Hãy liên hệ với hệ tuần hoàn kép ở người.","e":"Tim 4 ngăn tách hoàn toàn máu giàu ôxi (nửa trái) và máu giàu CO₂ (nửa phải), máu đi nuôi cơ thể là máu giàu ôxi nên hiệu quả vận chuyển và trao đổi khí cao.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Ở người, nước tiểu được tạo thành nhờ quá trình lọc máu diễn ra ở cơ quan nào?","o":["Gan","Bóng đái","Ống đái","Thận"],"a":"Thận","h":"Mỗi quả của cơ quan này chứa khoảng một triệu đơn vị chức năng là nephron.","e":"Thận là cơ quan bài tiết chính: máu được lọc qua các nephron của thận tạo thành nước tiểu, giúp thải chất cặn bã và điều hoà cân bằng nước, muối trong cơ thể.","t":"sinh-lop11","g":11,"l":"nhe-nhang"},{"p":"Gen là gì?","o":["Toàn bộ vật chất di truyền trong nhân tế bào","Một đoạn của phân tử protein","Đơn vị cấu tạo nên nhiễm sắc thể","Một đoạn của phân tử ADN mang thông tin mã hoá cho một sản phẩm nhất định (chuỗi pôlipeptit hoặc ARN)"],"a":"Một đoạn của phân tử ADN mang thông tin mã hoá cho một sản phẩm nhất định (chuỗi pôlipeptit hoặc ARN)","h":"Gen liên quan trực tiếp tới một sản phẩm: chuỗi pôlipeptit hoặc ARN.","e":"Gen là một đoạn ADN mang thông tin mã hoá cho một sản phẩm nhất định (chuỗi pôlipeptit hoặc ARN).","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Mã di truyền trên mARN được đọc theo đơn vị nào?","o":["Từng nuclêôtit một","Từng cặp nuclêôtit","Từng bộ bốn nuclêôtit","Từng bộ ba nuclêôtit (côđon)"],"a":"Từng bộ ba nuclêôtit (côđon)","h":"Cứ ba nuclêôtit liên tiếp trên mARN tạo thành một đơn vị mã hoá.","e":"Mã di truyền là mã bộ ba: cứ 3 nuclêôtit liên tiếp trên mARN tạo thành một côđon quy định một axit amin hoặc tín hiệu kết thúc.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Tính thoái hoá của mã di truyền có nghĩa là gì?","o":["Một bộ ba mã hoá cho nhiều loại axit amin","Mã di truyền bị thay đổi theo loài","Nhiều bộ ba khác nhau cùng mã hoá cho một loại axit amin","Bộ ba kết thúc cũng mã hoá axit amin"],"a":"Nhiều bộ ba khác nhau cùng mã hoá cho một loại axit amin","h":"Hãy nghĩ tới trường hợp nhiều côđon cùng quy định một axit amin.","e":"Tính thoái hoá: hầu hết axit amin được mã hoá bởi nhiều bộ ba; nhờ vậy một số đột biến thay thế nuclêôtit không làm đổi axit amin.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Bộ ba nào là bộ ba mở đầu quá trình dịch mã?","o":["UAA","UAG","UGA","AUG"],"a":"AUG","h":"Ba bộ ba UAA, UAG, UGA là bộ ba kết thúc.","e":"AUG là bộ ba mở đầu, đồng thời mã hoá axit amin mêtiônin; UAA, UAG, UGA là các bộ ba kết thúc.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Quá trình nhân đôi ADN diễn ra theo nguyên tắc bán bảo lưu, có nghĩa là gì?","o":["ADN con hoàn toàn mới, ADN mẹ bị phân huỷ","Mỗi ADN con giữ lại một nửa số nuclêôtit rải rác của mẹ","ADN mẹ giữ nguyên, ADN con là bản sao chép riêng","Mỗi ADN con gồm một mạch cũ của ADN mẹ và một mạch mới tổng hợp"],"a":"Mỗi ADN con gồm một mạch cũ của ADN mẹ và một mạch mới tổng hợp","h":"Mỗi phân tử ADN con vẫn giữ lại một mạch của ADN mẹ.","e":"Nguyên tắc bán bảo lưu: mỗi ADN con có một mạch khuôn của mẹ và một mạch mới được tổng hợp.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Enzim chính chịu trách nhiệm tổng hợp mạch ADN mới trong nhân đôi là enzim nào?","o":["ARN pôlimeraza","Ligaza","ADN pôlimeraza","Amilaza"],"a":"ADN pôlimeraza","h":"Đừng nhầm với enzim của quá trình phiên mã.","e":"ADN pôlimeraza là enzim chính tổng hợp mạch ADN mới; ARN pôlimeraza phục vụ phiên mã.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Trong một phân tử ADN, nuclêôtit loại A chiếm 20% tổng số nuclêôtit. Tỉ lệ phần trăm nuclêôtit loại G là bao nhiêu?","o":["30%","20%","40%","60%"],"a":"30%","h":"Dùng nguyên tắc bổ sung: %A = %T, %G = %X và tổng bằng 100%.","e":"Theo nguyên tắc bổ sung: %A = %T = 20%, nên %G = %X = (100% - 40%) : 2 = 30%.","t":"sinh-lop12","g":12,"l":"thu-thach"},{"p":"Quá trình phiên mã ở sinh vật nhân thực diễn ra chủ yếu ở đâu và tạo ra sản phẩm nào?","o":["Ở ribôxôm, tạo ra protein","Trong ti thể, tạo ra ADN mới","Trong nhân tế bào, tạo ra ARN từ khuôn một mạch của gen","Ở tế bào chất, tạo ra tARN từ protein"],"a":"Trong nhân tế bào, tạo ra ARN từ khuôn một mạch của gen","h":"Quá trình này cần khuôn là một mạch của gen và enzim ARN pôlimeraza.","e":"Phiên mã xảy ra trong nhân (ở sinh vật nhân thực), dùng một mạch của gen làm khuôn để tổng hợp ARN.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Trong quá trình dịch mã, phân tử nào vận chuyển axit amin tới ribôxôm?","o":["mARN","rARN","ADN","tARN"],"a":"tARN","h":"Phân tử này có bộ ba đối mã (anticôđon) khớp với côđon trên mARN.","e":"tARN mang axit amin tới ribôxôm và khớp bộ ba đối mã với côđon trên mARN.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Đột biến gen là gì?","o":["Biến đổi trong cấu trúc của gen liên quan tới một hoặc một số cặp nuclêôtit","Thay đổi số lượng nhiễm sắc thể trong tế bào","Biến đổi kiểu hình do môi trường mà không thay đổi kiểu gen","Sự tổ hợp lại các gen trong giảm phân"],"a":"Biến đổi trong cấu trúc của gen liên quan tới một hoặc một số cặp nuclêôtit","h":"Đột biến gen chỉ liên quan tới một hoặc vài cặp nuclêôtit trong gen.","e":"Đột biến gen là biến đổi nhỏ trong cấu trúc gen, liên quan đến một hoặc một số cặp nuclêôtit (thay thế, mất, thêm).","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Vì sao một đột biến thay thế một cặp nuclêôtit trong vùng mã hoá có thể không làm thay đổi axit amin trong chuỗi pôlipeptit?","o":["Vì cặp nuclêôtit đó luôn nằm ngoài gen","Vì ribôxôm tự sửa lại mọi đột biến","Do tính thoái hoá của mã di truyền, bộ ba mới vẫn mã hoá cùng một axit amin","Vì đột biến thay thế không bao giờ xảy ra ở vùng mã hoá"],"a":"Do tính thoái hoá của mã di truyền, bộ ba mới vẫn mã hoá cùng một axit amin","h":"Một axit amin có thể được mã hoá bởi nhiều bộ ba khác nhau.","e":"Do mã di truyền có tính thoái hoá, bộ ba sau đột biến vẫn có thể mã hoá đúng axit amin cũ (đột biến đồng nghĩa) nên chuỗi pôlipeptit không đổi.","t":"sinh-lop12","g":12,"l":"thu-thach"},{"p":"Mất đoạn, lặp đoạn, đảo đoạn, chuyển đoạn là các dạng của loại đột biến nào?","o":["Đột biến gen","Đột biến số lượng nhiễm sắc thể","Thường biến","Đột biến cấu trúc nhiễm sắc thể"],"a":"Đột biến cấu trúc nhiễm sắc thể","h":"Các dạng này làm thay đổi hình dạng, cấu trúc của nhiễm sắc thể chứ không phải số lượng.","e":"Mất đoạn, lặp đoạn, đảo đoạn, chuyển đoạn đều là đột biến cấu trúc nhiễm sắc thể.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Hội chứng Đao ở người là do dạng đột biến nào?","o":["Mất đoạn nhiễm sắc thể số 5","Đột biến gen trên nhiễm sắc thể X","Tăng thêm một bộ nhiễm sắc thể đơn bội","Thừa một nhiễm sắc thể ở cặp số 21 (thể ba nhiễm, 2n + 1)"],"a":"Thừa một nhiễm sắc thể ở cặp số 21 (thể ba nhiễm, 2n + 1)","h":"Người mắc hội chứng Đao có 47 nhiễm sắc thể trong tế bào.","e":"Hội chứng Đao do thể ba nhiễm ở cặp nhiễm sắc thể 21 (2n + 1 = 47), thuộc đột biến lệch bội.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Hiện tượng đa bội (toàn bộ bộ nhiễm sắc thể tăng lên theo bội số của n, lớn hơn 2n) phổ biến và dễ tạo loài mới nhất ở nhóm sinh vật nào?","o":["Thực vật","Động vật có vú","Chim","Cá"],"a":"Thực vật","h":"Ở động vật, đa bội thường gây chết hoặc bất thụ; ở thực vật lại khá phổ biến.","e":"Đa bội rất phổ biến ở thực vật và là con đường hình thành loài mới quan trọng; ở động vật bậc cao đa bội thường gây chết.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Thường biến có đặc điểm nào sau đây?","o":["Biến đổi kiểu gen và di truyền cho đời sau","Chỉ xuất hiện do đột biến gen","Biến đổi kiểu hình không di truyền, do tác động của môi trường","Luôn gây hại cho sinh vật"],"a":"Biến đổi kiểu hình không di truyền, do tác động của môi trường","h":"Thường biến không làm thay đổi vật chất di truyền.","e":"Thường biến chỉ là biến đổi kiểu hình dưới tác động của môi trường, kiểu gen không đổi nên không di truyền.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Phép lai phân tích được dùng để làm gì?","o":["Tạo ra giống thuần chủng","Kiểm tra kiểu gen của cá thể mang tính trạng trội","Xác định tần số hoán vị gen","Gây đột biến ở cá thể lai"],"a":"Kiểm tra kiểu gen của cá thể mang tính trạng trội","h":"Cá thể trội có thể là AA hoặc Aa; đem lai với cá thể lặn aa sẽ phân biệt được.","e":"Lai cá thể trội chưa biết kiểu gen với cá thể đồng hợp lặn: nếu đời con phân tính thì cá thể trội là dị hợp.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Cho cây đậu Hà Lan dị hợp một cặp gen tự thụ phấn: Aa × Aa. Tỉ lệ kiểu hình ở đời con (trội hoàn toàn) là bao nhiêu?","o":["1 trội : 2 trung gian : 1 lặn","3 trội : 1 lặn","1 trội : 1 lặn","9 : 3 : 3 : 1"],"a":"3 trội : 1 lặn","h":"Áp dụng quy luật phân li của Menđen: Aa cho hai loại giao tử tỉ lệ bằng nhau.","e":"Aa × Aa cho tỉ lệ kiểu gen 1 AA : 2 Aa : 1 aa, tương ứng tỉ lệ kiểu hình 3 trội : 1 lặn khi trội hoàn toàn.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Ở phép lai Aa × Aa, tỉ lệ kiểu gen ở đời con là bao nhiêu?","o":["3 AA : 1 aa","1 AA : 1 Aa : 1 aa","2 AA : 1 Aa : 1 aa","1 AA : 2 Aa : 1 aa"],"a":"1 AA : 2 Aa : 1 aa","h":"Đời con của Aa × Aa có ba kiểu gen với tỉ lệ đặc trưng 1 : 2 : 1.","e":"Tỉ lệ kiểu gen ở đời con của phép lai một cặp gen dị hợp là 1 AA : 2 Aa : 1 aa.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Cơ thể có kiểu gen AaBb (hai cặp gen phân li độc lập) khi giảm phân cho tối đa mấy loại giao tử?","o":["4 loại (AB, Ab, aB, ab)","2 loại","3 loại","8 loại"],"a":"4 loại (AB, Ab, aB, ab)","h":"Mỗi cặp gen dị hợp cho 2 loại giao tử; hai cặp cho 2 × 2 loại.","e":"Hai cặp gen phân li độc lập cho 4 loại giao tử AB, Ab, aB, ab với tỉ lệ bằng nhau.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Cho phép lai AaBb × AaBb với hai cặp tính trạng phân li độc lập, trội hoàn toàn. Tỉ lệ kiểu hình ở đời con là bao nhiêu?","o":["3 : 1","9 : 3 : 3 : 1","1 : 2 : 1","9 : 7"],"a":"9 : 3 : 3 : 1","h":"Đây là tỉ lệ kiểu hình kinh điển của quy luật phân li độc lập khi trội hoàn toàn.","e":"AaBb × AaBb cho tỉ lệ kiểu hình 9 : 3 : 3 : 1 theo quy luật phân li độc lập của Menđen.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Hiện tượng liên kết gen được Môcgan phát hiện trên đối tượng nào và có ý nghĩa gì?","o":["Trên ruồi giấm; các gen cùng nằm trên một nhiễm sắc thể có xu hướng di truyền cùng nhau","Trên đậu Hà Lan; các gen luôn phân li độc lập","Trên vi khuẩn; gen nằm ngoài nhiễm sắc thể","Trên ngô; các gen luôn hoán vị với tần số 50%"],"a":"Trên ruồi giấm; các gen cùng nằm trên một nhiễm sắc thể có xu hướng di truyền cùng nhau","h":"Thí nghiệm kinh điển này thực hiện trên ruồi giấm.","e":"Môcgan nghiên cứu trên ruồi giấm và phát hiện các gen cùng nằm trên một nhiễm sắc thể di truyền liên kết với nhau.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Hoán vị gen xảy ra do hiện tượng nào trong giảm phân?","o":["Phân li ngẫu nhiên của các nhiễm sắc thể","Nhân đôi nhiễm sắc thể ở kì trung gian","Tiếp hợp mà không trao đổi đoạn","Trao đổi chéo giữa các crômatit khác nguồn của cặp nhiễm sắc thể tương đồng"],"a":"Trao đổi chéo giữa các crômatit khác nguồn của cặp nhiễm sắc thể tương đồng","h":"Hiện tượng này xảy ra ở kì đầu của giảm phân I khi các nhiễm sắc thể tương đồng tiếp hợp.","e":"Hoán vị gen do trao đổi chéo giữa hai crômatit khác nguồn trong cặp nhiễm sắc thể tương đồng ở kì đầu giảm phân I.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Tần số hoán vị gen giữa hai gen liên kết không bao giờ vượt quá bao nhiêu phần trăm?","o":["25%","50%","75%","100%"],"a":"50%","h":"Khi tần số đạt giá trị này, kết quả giống như phân li độc lập.","e":"Tần số hoán vị gen luôn nhỏ hơn hoặc bằng 50%; đạt 50% thì kết quả như phân li độc lập.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Hai gen liên kết có tần số hoán vị là 20%. Mỗi loại giao tử hoán vị chiếm tỉ lệ bao nhiêu trong tổng số giao tử?","o":["10%","20%","40%","5%"],"a":"10%","h":"Giao tử hoán vị gồm hai loại, tổng tỉ lệ bằng tần số hoán vị.","e":"Tần số hoán vị 20% nghĩa là tổng giao tử hoán vị chiếm 20%, gồm hai loại bằng nhau nên mỗi loại chiếm 10%.","t":"sinh-lop12","g":12,"l":"thu-thach"},{"p":"Bệnh mù màu đỏ - lục ở người do gen lặn nằm trên nhiễm sắc thể X quy định. Đây là ví dụ về hình thức di truyền nào?","o":["Di truyền ngoài nhân","Di truyền liên kết hoàn toàn trên nhiễm sắc thể thường","Di truyền đa gen","Di truyền liên kết với giới tính"],"a":"Di truyền liên kết với giới tính","h":"Gen quy định bệnh nằm trên nhiễm sắc thể giới tính X.","e":"Gen mù màu nằm trên vùng không tương đồng của nhiễm sắc thể X, là ví dụ điển hình của di truyền liên kết giới tính.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Vốn gen của một quần thể được hiểu là gì?","o":["Tổng số cá thể có trong quần thể","Toàn bộ các alen của tất cả các gen có trong quần thể tại một thời điểm xác định","Toàn bộ kiểu hình biểu hiện trong quần thể","Số lượng gen có trong một tế bào"],"a":"Toàn bộ các alen của tất cả các gen có trong quần thể tại một thời điểm xác định","h":"Vốn gen được đặc trưng bởi tần số các alen và tần số các kiểu gen.","e":"Vốn gen gồm toàn bộ các alen của mọi gen trong quần thể tại một thời điểm, đặc trưng bởi tần số alen và tần số kiểu gen.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Theo định luật Hacđi - Vanbec, quần thể ngẫu phối sẽ đạt trạng thái cân bằng di truyền khi nào?","o":["Khi không có tác động của chọn lọc tự nhiên, đột biến, di - nhập gen và quần thể có kích thước lớn, giao phối ngẫu nhiên","Khi mọi cá thể đều có kiểu gen đồng hợp","Khi tần số các alen bằng nhau","Khi quần thể ngừng sinh sản"],"a":"Khi không có tác động của chọn lọc tự nhiên, đột biến, di - nhập gen và quần thể có kích thước lớn, giao phối ngẫu nhiên","h":"Chỉ cần một điều kiện bị phá vỡ, quần thể sẽ mất cân bằng.","e":"Quần thể cân bằng Hacđi - Vanbec khi giao phối ngẫu nhiên, kích thước lớn và không chịu tác động của chọn lọc tự nhiên, đột biến, di - nhập gen.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Một quần thể cân bằng Hacđi - Vanbec có tần số alen A là 0,6 và alen a là 0,4. Tần số kiểu gen dị hợp Aa là bao nhiêu?","o":["0,36","0,16","0,48","0,24"],"a":"0,48","h":"Tần số kiểu gen Aa trong quần thể cân bằng bằng 2pq.","e":"Tần số kiểu gen Aa = 2pq = 2 × 0,6 × 0,4 = 0,48.","t":"sinh-lop12","g":12,"l":"thu-thach"},{"p":"Trong quần thể cân bằng Hacđi - Vanbec với tần số alen A là 0,6, tần số kiểu gen đồng hợp trội AA bằng bao nhiêu?","o":["0,36","0,60","0,48","0,12"],"a":"0,36","h":"Tần số kiểu gen AA trong quần thể cân bằng bằng p bình phương.","e":"Tần số kiểu gen AA = p² = 0,6² = 0,36.","t":"sinh-lop12","g":12,"l":"thu-thach"},{"p":"Bằng chứng hoá thạch có ý nghĩa chủ yếu nào đối với nghiên cứu tiến hoá?","o":["Chứng minh mọi loài hiện nay đều không thay đổi","Cho biết lịch sử phát triển của sinh giới và trình tự xuất hiện của các nhóm sinh vật","Cho biết tuổi chính xác của Trái Đất","Là bằng chứng duy nhất về tiến hoá"],"a":"Cho biết lịch sử phát triển của sinh giới và trình tự xuất hiện của các nhóm sinh vật","h":"Hoá thạch là di tích của sinh vật sống trong các thời đại địa chất trước.","e":"Hoá thạch là bằng chứng trực tiếp, cho thấy sinh giới đã biến đổi theo thời gian và trình tự xuất hiện của các nhóm sinh vật.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Cặp cấu trúc nào sau đây là cơ quan tương đồng?","o":["Cánh bướm và cánh chim","Tay người và chi trước của ngựa","Cánh dơi và cánh côn trùng","Gai cây hoa hồng và gai cây xương rồng"],"a":"Tay người và chi trước của ngựa","h":"Cơ quan tương đồng có cùng nguồn gốc tiến hoá dù chức năng có thể khác nhau.","e":"Tay người và chi trước của ngựa có cùng nguồn gốc, cùng cấu trúc xương cơ bản nên là cơ quan tương đồng; các cặp còn lại là cơ quan tương tự.","t":"sinh-lop12","g":12,"l":"thu-thach"},{"p":"Theo học thuyết Đacuyn, động lực và cơ chế chính của quá trình tiến hoá là gì?","o":["Chọn lọc nhân tạo do con người tiến hành","Sự tập nhiễm các tính trạng do rèn luyện","Chọn lọc tự nhiên tác động lên các biến dị cá thể di truyền được","Đột biến xảy ra theo hướng xác định trước"],"a":"Chọn lọc tự nhiên tác động lên các biến dị cá thể di truyền được","h":"Đacuyn nhấn mạnh vai trò của biến dị cá thể và chọn lọc tự nhiên.","e":"Theo Đacuyn, chọn lọc tự nhiên giữ lại các biến dị cá thể có lợi, di truyền được, là cơ chế chính của tiến hoá.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Theo thuyết tiến hoá tổng hợp hiện đại, nguyên liệu sơ cấp cho quá trình tiến hoá là gì?","o":["Thường biến","Đột biến (biến dị di truyền)","Biến đổi do tập quán sinh hoạt","Ảnh hưởng trực tiếp của ngoại cảnh lên kiểu hình"],"a":"Đột biến (biến dị di truyền)","h":"Thuyết tổng hợp kết hợp di truyền học với học thuyết Đacuyn.","e":"Thuyết tiến hoá tổng hợp coi đột biến là nguồn nguyên liệu sơ cấp, còn chọn lọc tự nhiên là nhân tố tiến hoá cơ bản định hướng quá trình.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Chọn lọc tự nhiên tác động lên quần thể theo hướng nào?","o":["Làm mọi cá thể trong quần thể đều giống hệt nhau","Luôn tạo ra loài mới trong một thế hệ","Giữ lại và sinh sản mạnh hơn các cá thể mang biến dị có lợi, giúp quần thể thích nghi với môi trường","Loại bỏ hoàn toàn mọi biến dị"],"a":"Giữ lại và sinh sản mạnh hơn các cá thể mang biến dị có lợi, giúp quần thể thích nghi với môi trường","h":"Chọn lọc tự nhiên là quá trình phân hoá khả năng sống sót và sinh sản.","e":"Chọn lọc tự nhiên làm tăng tần số alen có lợi, giảm tần số alen có hại, giúp quần thể ngày càng thích nghi.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Điều kiện cần để hai quần thể của cùng một loài tách thành hai loài mới là gì?","o":["Xuất hiện cách li sinh sản giữa hai quần thể","Hai quần thể có số lượng cá thể bằng nhau","Hai quần thể sống trong cùng một khu vực","Cá thể của hai quần thể có hình thái giống hệt nhau"],"a":"Xuất hiện cách li sinh sản giữa hai quần thể","h":"Không còn trao đổi gen thực sự thì hai quần thể mới trở thành hai loài riêng.","e":"Loài mới chỉ hình thành khi có cách li sinh sản, tức hai quần thể không còn giao phối tạo đời con hữu thụ được nữa.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Nhóm nhân tố nào sau đây gồm toàn nhân tố sinh thái vô sinh?","o":["Cây xanh, vi khuẩn, nấm","Ánh sáng, nhiệt độ, độ ẩm, đất","Vật ăn thịt, con mồi, vật chủ","Con người và hoạt động sản xuất"],"a":"Ánh sáng, nhiệt độ, độ ẩm, đất","h":"Nhân tố vô sinh là các yếu tố không sống của môi trường.","e":"Ánh sáng, nhiệt độ, độ ẩm, đất là nhân tố vô sinh; sinh vật khác là nhân tố hữu sinh.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Quan hệ giữa vi khuẩn cố định đạm trong nốt sần rễ cây họ Đậu với cây chủ là quan hệ nào?","o":["Kí sinh","Cạnh tranh","Cộng sinh (cả hai bên cùng có lợi)","Hội sinh"],"a":"Cộng sinh (cả hai bên cùng có lợi)","h":"Cả cây họ Đậu và vi khuẩn đều nhận được lợi ích từ mối quan hệ này.","e":"Vi khuẩn cố định đạm nhận chất hữu cơ từ cây, cây nhận đạm dễ hấp thụ từ vi khuẩn: cả hai cùng lợi nên là cộng sinh.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Quan hệ vật ăn thịt - con mồi thuộc nhóm quan hệ nào trong quần xã?","o":["Quan hệ đối kháng","Quan hệ hỗ trợ","Quan hệ trung lập","Quan hệ hợp tác bắt buộc"],"a":"Quan hệ đối kháng","h":"Một bên được lợi, một bên bị hại là dấu hiệu của quan hệ đối kháng.","e":"Trong quan hệ vật ăn thịt - con mồi, một loài được lợi, loài kia bị hại nên thuộc quan hệ đối kháng.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Trong hệ sinh thái, khi năng lượng truyền qua mỗi bậc dinh dưỡng, phần lớn năng lượng bị mất đi chủ yếu do đâu?","o":["Được tích luỹ toàn bộ vào sinh khối bậc sau","Hô hấp và thoát nhiệt của sinh vật","Chuyển hoá thành khoáng chất ngay lập tức","Bị phản xạ hoàn toàn ra ngoài không gian"],"a":"Hô hấp và thoát nhiệt của sinh vật","h":"Chỉ khoảng 10% năng lượng được chuyển lên bậc dinh dưỡng tiếp theo.","e":"Phần lớn năng lượng qua mỗi bậc dinh dưỡng bị tiêu hao cho hô hấp và thoát ra dạng nhiệt, chỉ khoảng 10% tích luỹ sang bậc sau.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Biện pháp nào sau đây góp phần trực tiếp bảo vệ đa dạng sinh học?","o":["Khai thác triệt để rừng tự nhiên để trồng cây công nghiệp","Săn bắt các loài quý hiếm làm vật nuôi cảnh","Thành lập và bảo vệ các khu bảo tồn thiên nhiên, vườn quốc gia","Xả chất thải chưa xử lí ra sông hồ"],"a":"Thành lập và bảo vệ các khu bảo tồn thiên nhiên, vườn quốc gia","h":"Đa dạng sinh học cần được bảo vệ ngay tại nơi sinh sống của các loài.","e":"Khu bảo tồn và vườn quốc gia bảo vệ sinh cảnh sống tự nhiên, là biện pháp trực tiếp nhất để giữ đa dạng sinh học.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Nhóm nhân tố nào sau đây thuộc nhân tố sinh thái vô sinh?","o":["Ánh sáng, nhiệt độ, độ ẩm và nước","Cây xanh, động vật ăn cỏ và vi sinh vật","Quan hệ cạnh tranh giữa các cá thể cùng loài","Sự săn mồi của động vật ăn thịt"],"a":"Ánh sáng, nhiệt độ, độ ẩm và nước","h":"Nhân tố vô sinh là các yếu tố không sống của môi trường.","e":"Nhân tố sinh thái vô sinh gồm các yếu tố vật lí, hoá học như ánh sáng, nhiệt độ, độ ẩm, nước, đất. Các quan hệ giữa sinh vật với sinh vật thuộc nhân tố hữu sinh.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Đặc trưng nào sau đây cho biết số cá thể của quần thể trên một đơn vị diện tích hay thể tích?","o":["Tỉ lệ giới tính","Mật độ cá thể","Nhóm tuổi","Sự phân bố cá thể"],"a":"Mật độ cá thể","h":"Đặc trưng này được tính bằng số cá thể chia cho diện tích hoặc thể tích nơi sống.","e":"Mật độ cá thể là số lượng cá thể trên một đơn vị diện tích (hoặc thể tích), là đặc trưng cơ bản ảnh hưởng mạnh tới sức sinh sản và tỉ lệ tử vong của quần thể.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Trong quần xã, loài có số lượng cá thể nhiều nhất, sinh khối lớn và hoạt động mạnh, chi phối các loài khác được gọi là","o":["loài ngẫu nhiên","loài đặc trưng","loài thứ yếu","loài ưu thế"],"a":"loài ưu thế","h":"Tên loài này gắn với vai trò chiếm ưu thế trong quần xã.","e":"Loài ưu thế có số lượng, sinh khối lớn và mức hoạt động mạnh, đóng vai trò quan trọng chi phối quần xã, ví dụ cây gỗ lớn trong quần xã rừng.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Trong hệ sinh thái, năng lượng được truyền qua các bậc dinh dưỡng theo một chiều và phần lớn bị mất đi chủ yếu do","o":["hoạt động hô hấp của sinh vật ở mỗi bậc dinh dưỡng","quang hợp của sinh vật sản xuất ở bậc cao","sự phân giải chất hữu cơ thành chất vô cơ","sự tích lũy sinh khối ở sinh vật tiêu thụ"],"a":"hoạt động hô hấp của sinh vật ở mỗi bậc dinh dưỡng","h":"Ở mỗi bậc dinh dưỡng, sinh vật phải dùng năng lượng để duy trì sự sống.","e":"Qua mỗi bậc dinh dưỡng, phần lớn năng lượng bị tiêu hao qua hô hấp để duy trì các hoạt động sống và thải ra môi trường dưới dạng nhiệt, chỉ một phần nhỏ được chuyển lên bậc cao hơn.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Diễn thế sinh thái là quá trình","o":["biến đổi tuần hoàn của khí hậu theo mùa trong năm","tăng trưởng số lượng cá thể của một quần thể theo thời gian","biến đổi tuần tự của quần xã sinh vật qua các giai đoạn, tương ứng với sự biến đổi của môi trường","di cư của các loài động vật từ vùng này sang vùng khác"],"a":"biến đổi tuần tự của quần xã sinh vật qua các giai đoạn, tương ứng với sự biến đổi của môi trường","h":"Quá trình này diễn ra ở cấp độ quần xã, không phải quần thể.","e":"Diễn thế sinh thái là quá trình biến đổi tuần tự của quần xã qua các giai đoạn khác nhau, tương ứng với sự biến đổi của điều kiện môi trường, hướng tới quần xã tương đối ổn định.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Bệnh máu khó đông ở người do gen lặn nằm trên nhiễm sắc thể X quy định và không có alen tương ứng trên Y. Nhận định nào sau đây đúng về bệnh này?","o":["Bệnh gặp ở nữ giới nhiều hơn nam giới","Nam giới chỉ cần nhận một gen lặn từ mẹ là đã biểu hiện bệnh","Bố bị bệnh chắc chắn truyền bệnh cho tất cả con trai","Bệnh di truyền theo dòng mẹ qua tế bào chất"],"a":"Nam giới chỉ cần nhận một gen lặn từ mẹ là đã biểu hiện bệnh","h":"Nam giới chỉ có một nhiễm sắc thể X, nhận từ mẹ.","e":"Nam giới có kiểu gen XY nên chỉ cần nhận một alen lặn trên X từ mẹ là biểu hiện bệnh; vì vậy bệnh máu khó đông gặp ở nam nhiều hơn nữ, và thường được nghiên cứu qua phả hệ.","t":"sinh-lop12","g":12,"l":"nhe-nhang"},{"p":"Cùng một giống lúa, khi trồng ở ruộng được bón phân đầy đủ thì cho năng suất cao, còn ở ruộng thiếu dinh dưỡng thì năng suất thấp. Sự khác nhau về năng suất này là biểu hiện của","o":["đột biến gen","đột biến cấu trúc nhiễm sắc thể","biến dị tổ hợp","thường biến"],"a":"thường biến","h":"Kiểu gen không đổi, chỉ kiểu hình thay đổi theo điều kiện môi trường.","e":"Thường biến là những biến đổi kiểu hình của cùng một kiểu gen dưới tác động trực tiếp của môi trường, không di truyền được; mức phản ứng về năng suất của giống do kiểu gen quy định.","t":"sinh-lop12","g":12,"l":"nhe-nhang"}];